/* @autogenerated */
package net.civeira.phylax.feature.observe.viewer;

import java.time.OffsetDateTime;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Function;
import java.util.stream.Collectors;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.exception.NotFoundException;
import net.civeira.phylax.common.security.OperationContext;
import net.civeira.phylax.feature.observe.issue.EventContext;
import net.civeira.phylax.feature.observe.issue.IssueAggregator;
import net.civeira.phylax.feature.observe.issue.IssueFingerprint;
import net.civeira.phylax.feature.observe.observedissue.application.usecase.ignore.ObservedIssueIgnoreUsecase;
import net.civeira.phylax.feature.observe.observedissue.application.usecase.markresolved.ObservedIssueMarkResolvedUsecase;
import net.civeira.phylax.feature.observe.observedissue.application.usecase.reopen.ObservedIssueReopenUsecase;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssue;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssueReference;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssueStatusOptions;
import net.civeira.phylax.feature.observe.observedissue.domain.gateway.ObservedIssueFilter;
import net.civeira.phylax.feature.observe.observedissue.domain.gateway.ObservedIssueQueryRepositoryGateway;
import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSourceReference;
import net.civeira.phylax.feature.observe.source.SourceRegistry;
import net.civeira.phylax.feature.observe.store.ObsLog;
import net.civeira.phylax.feature.observe.store.TelemetryQuery;
import net.civeira.phylax.feature.observe.store.TelemetryStore;

/**
 * Issues for the viewer: the list (read directly, the api already checked the READ level) and the
 * triage, through the generated use cases so the policies of the model and the audit apply.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class ObserveIssues {

  private static final int MAX = 500;

  /** An issue as the viewer shows it (times in epoch milliseconds). */
  public record IssueRow(String uid, String source, String title, String culprit, String level,
      String status, int count, Long firstSeenAt, Long lastSeenAt, String lastTraceId,
      String firstRelease, String release, int users, int tenants, String kind, String assignee,
      String mergedInto, String trackerUrl, Long ignoreUntil, Integer ignoreUntilCount) {}

  private final ObservedIssueQueryRepositoryGateway issues;
  private final SourceRegistry registry;
  private final ObservedIssueMarkResolvedUsecase markResolved;
  private final ObservedIssueIgnoreUsecase ignore;
  private final ObservedIssueReopenUsecase reopen;
  private final TelemetryStore store;
  private final IssueAggregator aggregator;
  private final net.civeira.phylax.feature.observe.sourcemap.SourceMaps sourceMaps;
  private final net.civeira.phylax.feature.observe.metric.ObserveMetrics metrics;

  private static final long HOUR = 3_600_000L;
  private static final int DAYS = 7;
  private static final int EVENTS = 50;

  /** An event of the issue with its stack split in lines (own frames marked). */
  public record IssueEvent(ObsLog log, List<IssueFingerprint.Line> stack) {}

  /**
   * Detail of an issue: the row, its latest events (newest first), the occurrences per hour of the
   * last days and the distribution of the events by release, environment, browser and tenant. The
   * events are the error logs tagged with its fingerprint ({@link IssueAggregator#tag}).
   */
  public java.util.Optional<Map<String, Object>> detail(final String uid, final Long before) {
    Map<String, String> codes = registry.all().stream().collect(
        Collectors.toMap(SourceRegistry.Source::uid, SourceRegistry.Source::code, (a, b) -> a));
    return issues.list(ObservedIssueFilter.builder().uid(uid).build()).stream().findFirst()
        .map(issue -> {
          IssueRow row = row(issue, codes);
          long now = System.currentTimeMillis() + 60_000;
          long to = null == before ? now : before;
          long from = Math.max(now - DAYS * 24 * HOUR,
              null == row.firstSeenAt() ? now - DAYS * 24 * HOUR : row.firstSeenAt() - HOUR);
          List<ObsLog> events =
              store.logs(TelemetryQuery.builder().from(from).to(now).sources(Set.of(row.source()))
                  .fingerprint(java.util.Optional.of(issue.getFingerprint())).limit(5_000).build());
          Map<String, Object> detail = new java.util.LinkedHashMap<>();
          detail.put("issue", row);
          detail.put("events", events.stream().filter(log -> log.ts() < to).limit(EVENTS)
              .map(log -> new IssueEvent(log, symbolicated(log))).toList());
          List<net.civeira.phylax.feature.observe.metric.MetricPoint> points = metrics.issuePoints(
              row.source(), issue.getFingerprint(), now - DAYS * 24 * HOUR - HOUR, now);
          // The metric points outlive the logs (retention by level); the logs, before the points
          // existed
          detail.put("histogram",
              points.isEmpty() ? histogram(events, now) : histogramOf(points, now));
          detail.put("distribution", distribution(events));
          detail.put("sampled", events.size());
          return detail;
        });
  }

  /**
   * The stack of an event, with the frames of a front translated to their original source when its
   * build uploaded the source maps of that release (the minified frame stays between brackets).
   */
  private List<IssueFingerprint.Line> symbolicated(final ObsLog log) {
    return IssueFingerprint.lines(log.error(), aggregator.inApp()).stream()
        .map(line -> !line.frame() ? line
            : sourceMaps.symbolicate(log.src(), log.release(), line.text())
                .map(original -> new IssueFingerprint.Line(
                    original + "   [" + line.text().trim() + "]", true,
                    !original.contains("node_modules")))
                .orElse(line))
        .toList();
  }

  /** Events per hour of the last days, oldest first: {@code {from, bucketMs, counts}}. */
  static Map<String, Object> histogram(final List<ObsLog> events, final long now) {
    int buckets = DAYS * 24;
    long end = (now / HOUR + 1) * HOUR;
    long start = end - buckets * HOUR;
    long[] counts = new long[buckets];
    for (ObsLog log : events) {
      int index = (int) ((log.ts() - start) / HOUR);
      if (index >= 0 && index < buckets) {
        counts[index]++;
      }
    }
    return Map.of("from", start, "bucketMs", HOUR, "counts", counts);
  }

  /** Occurrences per hour of the last days from the metric points of the issue. */
  static Map<String, Object> histogramOf(
      final List<net.civeira.phylax.feature.observe.metric.MetricPoint> points, final long now) {
    int buckets = DAYS * 24;
    long end = (now / HOUR + 1) * HOUR;
    long start = end - buckets * HOUR;
    long[] counts = new long[buckets];
    for (var point : points) {
      int index = (int) ((point.ts() - start) / HOUR);
      if (index >= 0 && index < buckets) {
        counts[index] += point.count();
      }
    }
    return Map.of("from", start, "bucketMs", HOUR, "counts", counts);
  }

  /** Top values of release, environment, browser and tenant among the events. */
  static Map<String, List<Map<String, Object>>> distribution(final List<ObsLog> events) {
    Map<String, Map<String, Long>> counts = new java.util.LinkedHashMap<>();
    for (String field : List.of("release", "environment", "browser", "tenant")) {
      counts.put(field, new java.util.HashMap<>());
    }
    for (ObsLog log : events) {
      EventContext context = EventContext.of(log.attrs());
      counts.get("release").merge(null == log.release() ? "unknown" : log.release(), 1L, Long::sum);
      counts.get("environment").merge(null == log.env() ? "unknown" : log.env(), 1L, Long::sum);
      counts.get("browser").merge(browser(context.userAgent()), 1L, Long::sum);
      counts.get("tenant").merge(null == context.tenant() ? "unknown" : context.tenant(), 1L,
          Long::sum);
    }
    Map<String, List<Map<String, Object>>> result = new java.util.LinkedHashMap<>();
    counts.forEach((field, values) -> result.put(field,
        values.entrySet().stream().sorted(Map.Entry.<String, Long>comparingByValue().reversed())
            .limit(5)
            .map(
                entry -> Map.<String, Object>of("value", entry.getKey(), "count", entry.getValue()))
            .toList()));
    return result;
  }

  /** Family of a user agent (enough for the distribution; not a full parser). */
  static String browser(final String userAgent) {
    if (null == userAgent || userAgent.isBlank()) {
      return "unknown";
    }
    String ua = userAgent.toLowerCase(java.util.Locale.ROOT);
    if (ua.contains("edg/")) {
      return "Edge";
    }
    if (ua.contains("firefox/")) {
      return "Firefox";
    }
    if (ua.contains("chrome/") || ua.contains("crios/")) {
      return "Chrome";
    }
    if (ua.contains("safari/")) {
      return "Safari";
    }
    if (ua.startsWith("curl/")) {
      return "curl";
    }
    if (ua.contains("java") || ua.contains("okhttp") || ua.contains("python")
        || ua.contains("go-http")) {
      return "server";
    }
    return "other";
  }

  /** Issues by last occurrence, newest first; filtered by source codes and status. */
  public List<IssueRow> list(final Set<String> sources, final String status, final String kind) {
    Map<String, String> codes = registry.all().stream().collect(
        Collectors.toMap(SourceRegistry.Source::uid, SourceRegistry.Source::code, (a, b) -> a));
    ObservedIssueFilter.ObservedIssueFilterBuilder filter = ObservedIssueFilter.builder();
    if (null != status && !status.isBlank()) {
      filter.status(ObservedIssueStatusOptions.fromValue(status));
    }
    if (null != kind && !kind.isBlank()) {
      filter.kind(net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssueKindOptions
          .fromValue(kind));
    }
    if (sources.size() == 1) {
      registry.byCode(sources.iterator().next())
          .ifPresent(source -> filter.origin(ObservedSourceReference.of(source.uid())));
    }
    return issues.list(filter.build()).stream().map(issue -> row(issue, codes))
        .filter(row -> sources.isEmpty() || sources.contains(row.source())).sorted(Comparator
            .comparing(IssueRow::lastSeenAt, Comparator.nullsLast(Comparator.reverseOrder())))
        .limit(MAX).toList();
  }

  /** Runs a triage action: mark-resolved, ignore or reopen. */
  public Object act(final OperationContext context, final String uid, final String action) {
    ObservedIssueReference reference = ObservedIssueReference.of(uid);
    Map<String, Function<ObservedIssueReference, Object>> actions =
        Map.of("mark-resolved", ref -> markResolved.markResolved(context, ref), "ignore",
            ref -> ignore.ignore(context, ref), "reopen", ref -> reopen.reopen(context, ref));
    Function<ObservedIssueReference, Object> run = actions.get(action);
    if (null == run) {
      throw new NotFoundException("Unknown action " + action);
    }
    return run.apply(reference);
  }

  private static IssueRow row(final ObservedIssue issue, final Map<String, String> codes) {
    String origin = issue.getOriginUid();
    return new IssueRow(issue.getUid(), codes.getOrDefault(origin, origin), issue.getTitle(),
        issue.getCulprit().orElse(null), issue.getLevel().name(), issue.getStatus().name(),
        null == issue.getCount() ? 0 : issue.getCount(),
        issue.getFirstSeenAt().map(ObserveIssues::millis).orElse(null),
        issue.getLastSeenAt().map(ObserveIssues::millis).orElse(null),
        issue.getLastTraceId().orElse(null), issue.getFirstRelease().orElse(null),
        issue.getRelease().orElse(null), null == issue.getUsers() ? 0 : issue.getUsers(),
        null == issue.getTenants() ? 0 : issue.getTenants(),
        null == issue.getKind() ? "ERROR" : issue.getKind().name(),
        issue.getAssignee().filter(value -> !value.isBlank()).orElse(null),
        issue.getMergedInto().orElse(null),
        issue.getTrackerUrl().filter(value -> !value.isBlank()).orElse(null),
        issue.getIgnoreUntil().map(ObserveIssues::millis).orElse(null),
        issue.getIgnoreUntilCount().orElse(null));
  }

  private static Long millis(final OffsetDateTime time) {
    return time.toInstant().toEpochMilli();
  }
}
